-- V8 · Point of sale and payments — FR-POS, FR-PAY, BR-3, BR-5, BR-6, BR-7, BR-11
--
-- BR-11: amounts are integer pesewas. Per-unit *rates* keep four decimals
-- (see V4); what a line, a sale or a payment settles to is an integer, because
-- money that can carry a fraction of a pesewa eventually fails to add up.

CREATE TYPE sale_status AS ENUM ('COMPLETED', 'VOIDED');

CREATE TYPE payment_method AS ENUM ('cash', 'momo', 'card', 'transfer');

-- ------------------------------------------------------------- sales · FR-POS

CREATE TABLE sale (
    -- BR-7: generated by the client, not the database. A double-click, a retry
    -- or a reconnect submits the same id, and the primary key is what makes the
    -- second one lose. Server-side generation cannot do that.
    id               UUID         PRIMARY KEY,

    -- BR-6: {OUTLET}-{TERMINAL}-{SEQ}, gapless per outlet and never reused.
    receipt_number   TEXT         NOT NULL UNIQUE,

    outlet_id        UUID         NOT NULL REFERENCES outlet (id),
    terminal_id      UUID         REFERENCES terminal (id),
    cashier_id       UUID         NOT NULL REFERENCES app_user (id),

    customer_id      UUID,        -- L adds the table; no FK until it exists
    customer_name    TEXT,
    customer_phone   TEXT,

    subtotal         BIGINT       NOT NULL,
    discount_total   BIGINT       NOT NULL DEFAULT 0,
    total            BIGINT       NOT NULL,
    change_due       BIGINT       NOT NULL DEFAULT 0,

    -- BR-3: completed sales are immutable. A void sets these and writes
    -- reversing movements; the sale itself is never deleted or edited.
    status           sale_status  NOT NULL DEFAULT 'COMPLETED',
    void_reason      TEXT,
    voided_by        UUID         REFERENCES app_user (id),
    voided_at        TIMESTAMPTZ,

    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    synced_at        TIMESTAMPTZ,

    CONSTRAINT sale_totals_not_negative CHECK (subtotal >= 0 AND total >= 0 AND change_due >= 0),
    -- A void without a reason is not a record of anything.
    CONSTRAINT sale_void_has_reason CHECK (
        (status = 'COMPLETED' AND void_reason IS NULL AND voided_at IS NULL)
        OR (status = 'VOIDED' AND void_reason IS NOT NULL AND voided_at IS NOT NULL))
);

CREATE INDEX idx_sale_outlet_created ON sale (outlet_id, created_at DESC);
CREATE INDEX idx_sale_cashier_created ON sale (cashier_id, created_at DESC);
CREATE INDEX idx_sale_customer ON sale (customer_id) WHERE customer_id IS NOT NULL;
-- FR-POS-18: searching past transactions by receipt number.
CREATE INDEX idx_sale_receipt_trgm ON sale USING gin (receipt_number gin_trgm_ops);

CREATE TABLE sale_item (
    id                UUID           PRIMARY KEY DEFAULT gen_random_uuid(),
    sale_id           UUID           NOT NULL REFERENCES sale (id) ON DELETE CASCADE,
    product_id        UUID           NOT NULL REFERENCES product (id),

    -- What the cashier chose, and what it meant in base units — FR-UOM-03.
    -- Both are kept: the receipt says "1 Drum 100m", the ledger says 100 m.
    selected_unit     TEXT           NOT NULL,
    conversion_factor NUMERIC(14,4)  NOT NULL,
    quantity          NUMERIC(14,3)  NOT NULL,
    quantity_base     NUMERIC(14,3)  NOT NULL,

    unit_price        NUMERIC(12,4)  NOT NULL,
    discount          BIGINT         NOT NULL DEFAULT 0,
    line_total        BIGINT         NOT NULL,

    -- BR-5: the cost at the moment of sale, frozen. A later purchase must never
    -- change historical profit.
    frozen_cost_price NUMERIC(12,4)  NOT NULL DEFAULT 0,

    -- BR-10: who authorised a price below the floor, recorded on the line that
    -- needed it rather than on the sale, because only that line was discounted.
    floor_approved_by UUID           REFERENCES app_user (id),

    CONSTRAINT sale_item_quantity_positive CHECK (quantity > 0 AND quantity_base > 0),
    CONSTRAINT sale_item_factor_positive CHECK (conversion_factor > 0)
);

CREATE INDEX idx_sale_item_sale ON sale_item (sale_id);
CREATE INDEX idx_sale_item_product ON sale_item (product_id);

-- ------------------------------------------------------------- payments · FR-PAY

CREATE TABLE payment (
    -- FR-PAY-07 · BR-7: client-generated, so resubmitting the same payment is
    -- rejected by the key rather than by a check that two requests can race.
    id           UUID            PRIMARY KEY,
    sale_id      UUID            NOT NULL REFERENCES sale (id) ON DELETE CASCADE,

    method       payment_method  NOT NULL,
    amount       BIGINT          NOT NULL,

    -- FR-PAY-03: MoMo, card and transfer carry a reference the cashier typed
    -- off the customer's phone or terminal slip.
    provider     TEXT,
    reference    TEXT,

    created_at   TIMESTAMPTZ     NOT NULL DEFAULT now(),
    synced_at    TIMESTAMPTZ,

    CONSTRAINT payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX idx_payment_sale ON payment (sale_id);

-- ------------------------------------------------------------- immutability

-- BR-3: a sale is evidence. The only permitted change is the void, which is why
-- this allows exactly that transition and nothing else.
CREATE OR REPLACE FUNCTION reject_sale_mutation() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'a sale is never deleted: void it instead';
    END IF;
    IF OLD.status = 'VOIDED' THEN
        RAISE EXCEPTION 'a voided sale cannot be changed again';
    END IF;
    IF NEW.status = OLD.status THEN
        RAISE EXCEPTION 'a completed sale cannot be edited: void it instead';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER sale_immutable
    BEFORE UPDATE OR DELETE ON sale
    FOR EACH ROW EXECUTE FUNCTION reject_sale_mutation();

-- Lines and payments belong to the sale and are never amended on their own.
CREATE OR REPLACE FUNCTION reject_sale_child_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'sale lines and payments are immutable';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER sale_item_immutable
    BEFORE UPDATE ON sale_item
    FOR EACH ROW EXECUTE FUNCTION reject_sale_child_mutation();

CREATE TRIGGER payment_immutable
    BEFORE UPDATE ON payment
    FOR EACH ROW EXECUTE FUNCTION reject_sale_child_mutation();
